/**
 * @summary List all evaluation runs
 */
export const getListEvalRunsUrl = (params?: ListEvalRunsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/eval-runs?${stringifiedParams}`
    : `/api/eval-runs`;
};

export const listEvalRuns = async (
  params?: ListEvalRunsParams,
  options?: RequestInit,
): Promise<EvalRun[]> => {
  return customFetch<EvalRun[]>(getListEvalRunsUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getListEvalRunsQueryKey = (params?: ListEvalRunsParams) => {
  return [`/api/eval-runs`, ...(params ? [params] : [])] as const;
};

